package com.nigson.acceptance.cart;
import com.nigson.commerce.cart.*;
import com.nigson.shared.problem.Problem;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.junit.jupiter.api.*;
import java.util.*;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;
class CartPersistenceTest {
 CartFixture fixture;
 @BeforeEach void setup(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null,"cart-check supplies isolated PostgreSQL");if(!url.matches("jdbc:postgresql://127.0.0.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_TEST_DB_REQUIRED");var ds=new DriverManagerDataSource(url+"?currentSchema=commerce","nigson_commerce_app","mock-commerce-runtime");fixture=new CartFixture(new JdbcTemplate(ds),new DataSourceTransactionManager(ds));}
 @AfterEach void cleanup(){if(fixture!=null)fixture.close();}
 @Test void createsOrReturnsOnlyActiveContextWithAtomicAudit(){var f=fixture.f;var carts=fixture.carts;var before=carts.get(f.customer,f.cart);var input=new CartValues.Create(f.market,null);assertThat(carts.create(f.customer,input,"existing",UUID.randomUUID())).isEqualTo(before);assertThat(carts.create(f.customer,input,"existing",UUID.randomUUID())).isEqualTo(before);assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.audit_record WHERE resource_id=? AND action='CART_CREATE'",Integer.class,f.cart)).isZero();f.jdbc.update("UPDATE commerce.cart SET status='EXPIRED' WHERE id=?",f.cart);var fresh=carts.create(f.customer,input,"fresh",UUID.randomUUID());assertThat(fresh.id()).isNotEqualTo(f.cart);assertThat(fresh.lines()).isEmpty();assertThat(fresh.state()).isEqualTo("ACTIVE");assertThat(fresh.version()).isZero();assertThat(carts.create(f.customer,input,"another",UUID.randomUUID())).isEqualTo(fresh);assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.audit_record WHERE resource_id=? AND action='CART_CREATE'",Integer.class,fresh.id())).isEqualTo(1);assertThat(f.metrics.get("nigson.cart.commands").tag("operation","CREATE").counter().count()).isEqualTo(1);}
 @Test void changesVersionActivityAndInvalidatesCarrierWithoutReserving(){var f=fixture.f;f.retail();var c=fixture.carts.get(f.customer,f.cart);var changed=fixture.carts.set(f.customer,f.cart,f.sku,0,new CartValues.Quantity("3"),"set",UUID.randomUUID());assertThat(changed.version()).isEqualTo(1);assertThat(changed.lines().getFirst().quantity()).isEqualTo("3");assertThat(changed.lastActivityAt()).isAfterOrEqualTo(c.lastActivityAt());assertThat(fixture.carts.set(f.customer,f.cart,f.sku,0,new CartValues.Quantity("3"),"set",UUID.randomUUID())).isEqualTo(changed);assertThatThrownBy(()->fixture.carts.set(f.customer,f.cart,f.sku,0,new CartValues.Quantity("4"),"stale",UUID.randomUUID())).hasMessage("VERSION_MISMATCH");assertThatThrownBy(()->f.quotes.create(f.customer,f.quoteInput(),"stale-quote",UUID.randomUUID())).hasMessage("PRICING_RULE_VIOLATION");assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.inventory_reservation r JOIN commerce.inventory_balance b ON b.id=r.balance_id WHERE b.sku_id=?",Integer.class,f.sku)).isZero();assertThat(fixture.carts.get(f.customer,f.cart)).isEqualTo(changed);var deleted=fixture.carts.remove(f.customer,f.cart,f.sku,1,"delete",UUID.randomUUID());assertThat(deleted.version()).isEqualTo(2);assertThat(fixture.carts.remove(f.customer,f.cart,f.sku,1,"delete",UUID.randomUUID())).isEqualTo(deleted);assertThat(fixture.carts.get(f.customer,f.cart).lines()).isEmpty();assertThatThrownBy(()->fixture.carts.remove(f.customer,f.cart,f.sku,2,"missing",UUID.randomUUID())).hasMessage("NOT_FOUND");}
 @Test void ownerAndCurrentPartyChecksPrecedeCachedAcknowledgment(){var f=fixture.f;f.retail();fixture.carts.set(f.customer,f.cart,f.sku,0,new CartValues.Quantity("3"),"set",UUID.randomUUID());assertThatThrownBy(()->fixture.carts.get(f.finance,f.cart)).hasMessage("NOT_FOUND");assertThatThrownBy(()->fixture.carts.set(f.finance,f.cart,f.sku,0,new CartValues.Quantity("3"),"set",UUID.randomUUID())).hasMessage("NOT_FOUND");f.jdbc.update("UPDATE commerce.party SET status='SUSPENDED' WHERE id=?",f.customer.party());assertThatThrownBy(()->fixture.carts.set(f.customer,f.cart,f.sku,0,new CartValues.Quantity("3"),"set",UUID.randomUUID())).hasMessage("ACCESS_DENIED");f.jdbc.update("UPDATE commerce.party SET status='ACTIVE' WHERE id=?",f.customer.party());}
 @Test void invalidCurrentScalePackEligibilityAndStateLeaveCartUnchanged(){var f=fixture.f;f.retail();var before=fixture.carts.get(f.customer,f.cart);assertThatThrownBy(()->fixture.carts.set(f.customer,f.cart,f.sku,0,new CartValues.Quantity("1.001"),"scale",UUID.randomUUID())).hasMessage("CART_RULE_VIOLATION");f.jdbc.update("UPDATE commerce.product_market_eligibility SET eligible=false WHERE product_id=? AND market_id=?",f.marketFixture.product,f.market);assertThatThrownBy(()->fixture.carts.set(f.customer,f.cart,f.sku,0,new CartValues.Quantity("3"),"eligibility",UUID.randomUUID())).hasMessage("CART_RULE_VIOLATION");assertThat(fixture.carts.get(f.customer,f.cart)).isEqualTo(before);f.jdbc.update("UPDATE commerce.cart SET status='CHECKOUT_PENDING' WHERE id=?",f.cart);assertThatThrownBy(()->fixture.carts.remove(f.customer,f.cart,f.sku,0,"pending",UUID.randomUUID())).hasMessage("INVALID_TRANSITION");f.jdbc.update("UPDATE commerce.cart SET status='ACTIVE' WHERE id=?",f.cart);f.jdbc.update("UPDATE commerce.sku SET active=false WHERE id=?",f.sku);assertThat(fixture.carts.remove(f.customer,f.cart,f.sku,0,"inactive-delete",UUID.randomUUID()).version()).isEqualTo(1);}
 @Test void auditFailureRollsBackLineVersionActivityAndCommand(){var f=fixture.f;f.retail();var before=fixture.carts.get(f.customer,f.cart);f.admin.execute("REVOKE INSERT ON commerce.audit_record FROM nigson_commerce_app");try{assertThatThrownBy(()->fixture.carts.set(f.customer,f.cart,f.sku,0,new CartValues.Quantity("3"),"audit-failure",UUID.randomUUID())).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(fixture.carts.get(f.customer,f.cart)).isEqualTo(before);assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.idempotency_record WHERE principal_key=? AND operation='API-034' AND request_key='audit-failure' AND state='SUCCEEDED'",Integer.class,f.customer.party().toString())).isZero();}finally{f.admin.execute("GRANT INSERT ON commerce.audit_record TO nigson_commerce_app");}assertThat(fixture.carts.set(f.customer,f.cart,f.sku,0,new CartValues.Quantity("3"),"audit-failure",UUID.randomUUID()).version()).isEqualTo(1);}
 @Test void organizationRevocationDeniesReplayAndSeparateContextIsUnique(){var f=fixture.f;UUID org=f.organization();var input=new CartValues.Create(f.market,org);var created=fixture.carts.create(f.customer,input,"org-create",UUID.randomUUID());assertThat(created.id()).isNotEqualTo(f.cart);assertThat(created.organizationId()).isEqualTo(org);assertThat(fixture.carts.create(f.customer,input,"org-create2",UUID.randomUUID())).isEqualTo(created);f.jdbc.update("UPDATE commerce.account_entitlement SET status='SUSPENDED' WHERE organization_id=?",org);assertThatThrownBy(()->fixture.carts.create(f.customer,input,"org-create",UUID.randomUUID())).hasMessage("ACCESS_DENIED");assertThatThrownBy(()->fixture.carts.get(f.customer,created.id())).hasMessage("ACCESS_DENIED");}
 @Test void racingCreatesHaveOneContextAndOneAudit()throws Exception{var f=fixture.f;f.jdbc.update("UPDATE commerce.cart SET status='EXPIRED' WHERE id=?",f.cart);var input=new CartValues.Create(f.market,null);try(var pool=Executors.newFixedThreadPool(8)){var start=new CountDownLatch(1);var work=new ArrayList<Future<Object>>();for(int n=0;n<8;n++){String key="create-race-"+n;work.add(pool.submit(()->{start.await();try{return fixture.carts.create(f.customer,input,key,UUID.randomUUID());}catch(Problem.Failure e){return e.getMessage();}}));}start.countDown();var ids=new HashSet<UUID>();for(var future:work){var result=future.get(20,TimeUnit.SECONDS);if(result instanceof CartValues.Cart c)ids.add(c.id());else assertThat(result).isEqualTo("IDEMPOTENCY_IN_PROGRESS");}assertThat(ids).hasSize(1);assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.cart WHERE party_id=? AND market_id=? AND status='ACTIVE'",Integer.class,f.customer.party(),f.market)).isEqualTo(1);assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.audit_record WHERE resource_id=? AND action='CART_CREATE'",Integer.class,ids.iterator().next())).isEqualTo(1);}}
 @Test void concurrentSameVersionHasOneMutation()throws Exception{var f=fixture.f;f.retail();try(var pool=Executors.newFixedThreadPool(2)){var start=new CountDownLatch(1);var work=new ArrayList<Future<Object>>();for(int n=0;n<2;n++){String key="set-race-"+n;work.add(pool.submit(()->{start.await();try{return fixture.carts.set(f.customer,f.cart,f.sku,0,new CartValues.Quantity("3"),key,UUID.randomUUID());}catch(Problem.Failure e){return e.getMessage();}}));}start.countDown();int wins=0;for(var future:work){var result=future.get(20,TimeUnit.SECONDS);if(result instanceof CartValues.Cart)wins++;else assertThat(result).isIn("VERSION_MISMATCH","IDEMPOTENCY_IN_PROGRESS");}assertThat(wins).isEqualTo(1);assertThat(fixture.carts.get(f.customer,f.cart).version()).isEqualTo(1);assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.audit_record WHERE resource_id=? AND action='CART_SET'",Integer.class,f.cart)).isEqualTo(1);}}
 private UUID order(){var f=fixture.f;UUID id=UUID.randomUUID();f.jdbc.update("INSERT INTO commerce.sales_order(id,created_by,updated_by,order_number,party_id,market_id,cart_id,status,payment_status,fulfillment_status,currency_code,subtotal,discount_total,tax_total,delivery_total,grand_total,address_snapshot,commercial_snapshot,carrier_quote_id,carrier_snapshot) VALUES (?,'test','test',?,?,?,?,'PENDING','PENDING','UNFULFILLED','NGN',24.68,0,0,3.45,28.13,'{}'::jsonb,'{}'::jsonb,?,'{}'::jsonb)",id,"SYN_"+id,f.customer.party(),f.market,f.cart,f.carrier);return id;}
 private org.springframework.transaction.support.TransactionTemplate tx(){return new org.springframework.transaction.support.TransactionTemplate(fixture.f.manager);}
 @Test void checkoutGuardAndParentRollbackAreAtomic(){var f=fixture.f;f.retail();var quote=f.quotes.create(f.customer,f.quoteInput(),"quote",UUID.randomUUID());UUID order=order();assertThatThrownBy(()->fixture.checkout.pending(f.customer.party(),f.cart,0,quote.id(),quote.quoteHash(),order,UUID.randomUUID())).hasMessage("LOCAL_TRANSACTION_REQUIRED");tx().execute(s->{assertThatThrownBy(()->fixture.checkout.pending(f.customer.party(),f.cart,0,quote.id(),"0".repeat(64),order,UUID.randomUUID())).hasMessage("CHECKOUT_REPRICE_REQUIRED");return null;});tx().execute(s->{assertThat(fixture.checkout.pending(f.customer.party(),f.cart,0,quote.id(),quote.quoteHash(),order,UUID.randomUUID()).state()).isEqualTo("CHECKOUT_PENDING");s.setRollbackOnly();return null;});assertThat(fixture.carts.get(f.customer,f.cart).version()).isZero();assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.audit_record WHERE resource_id=? AND action='CART_TRANSITION'",Integer.class,f.cart)).isZero();tx().execute(s->fixture.checkout.pending(f.customer.party(),f.cart,0,quote.id(),quote.quoteHash(),order,UUID.randomUUID()));assertThatThrownBy(()->fixture.carts.set(f.customer,f.cart,f.sku,1,new CartValues.Quantity("3"),"pending-change",UUID.randomUUID())).hasMessage("INVALID_TRANSITION");}
 @Test void expiryNeverConvertsUnknownIntoFailureAndLateVerifiedTruthConvertsOnce(){var f=fixture.f;f.retail();var quote=f.quotes.create(f.customer,f.quoteInput(),"quote",UUID.randomUUID());UUID order=order(),attempt=UUID.randomUUID();tx().execute(s->fixture.checkout.pending(f.customer.party(),f.cart,0,quote.id(),quote.quoteHash(),order,UUID.randomUUID()));f.jdbc.update("INSERT INTO commerce.payment_attempt(id,created_by,updated_by,order_id,provider,reference,merchant_account,expected_amount,currency_code,state,provider_mode) VALUES (?,'test','test',?,'PAYSTACK',?,'SYNTHETIC_NOT_QUALIFIED',28.13,'NGN','UNKNOWN','MOCK')",attempt,order,"SYNTH_"+attempt);f.jdbc.update("UPDATE commerce.sales_order SET status='CANCELLED',payment_status='UNPAID' WHERE id=?",order);tx().execute(s->{assertThatThrownBy(()->fixture.checkout.expired(order,UUID.randomUUID())).hasMessage("CART_RULE_VIOLATION");return null;});assertThat(f.jdbc.queryForObject("SELECT state FROM commerce.payment_attempt WHERE id=?",String.class,attempt)).isEqualTo("UNKNOWN");assertThat(fixture.carts.get(f.customer,f.cart).state()).isEqualTo("CHECKOUT_PENDING");f.jdbc.update("UPDATE commerce.payment_attempt SET state='FAILED',verified_at=now() WHERE id=?",attempt);var expired=tx().execute(s->fixture.checkout.expired(order,UUID.randomUUID()));assertThat(expired.state()).isEqualTo("EXPIRED");assertThat(tx().<CartValues.Cart>execute(s->fixture.checkout.expired(order,UUID.randomUUID()))).isEqualTo(expired);f.jdbc.update("UPDATE commerce.sales_order SET status='PAYMENT_HOLD',payment_status='PAID' WHERE id=?",order);tx().execute(s->{assertThatThrownBy(()->fixture.checkout.converted(order,UUID.randomUUID())).hasMessage("CART_RULE_VIOLATION");return null;});f.jdbc.update("UPDATE commerce.payment_attempt SET state='SUCCEEDED',verified_at=now() WHERE id=?",attempt);f.jdbc.update("INSERT INTO commerce.payment_transaction(id,created_by,attempt_id,provider_transaction_id,settled_amount,currency_code,provider_status,settled_at,verification_hash,provider_mode) VALUES (?,'test',?,?,28.13,'NGN','success',now(),?,'MOCK')",UUID.randomUUID(),attempt,"SYNTH_"+attempt,"a".repeat(64));var converted=tx().execute(s->fixture.checkout.converted(order,UUID.randomUUID()));assertThat(converted.state()).isEqualTo("CONVERTED");assertThat(tx().<CartValues.Cart>execute(s->fixture.checkout.converted(order,UUID.randomUUID()))).isEqualTo(converted);assertThat(f.jdbc.queryForObject("SELECT converted_order_id FROM commerce.cart WHERE id=?",UUID.class,f.cart)).isEqualTo(order);assertThatThrownBy(()->fixture.carts.remove(f.customer,f.cart,f.sku,converted.version(),"converted-remove",UUID.randomUUID())).hasMessage("INVALID_TRANSITION");}
 @Test void recoveryAgeIsOnlyEligibilityAndRequiresActiveNonemptyNoOrder(){var f=fixture.f;assertThat(tx().<Boolean>execute(s->fixture.checkout.recoveryEligible(f.customer.party(),f.cart))).isFalse();f.jdbc.update("UPDATE commerce.cart SET last_activity_at=now()-interval '25 hours' WHERE id=?",f.cart);assertThat(tx().<Boolean>execute(s->fixture.checkout.recoveryEligible(f.customer.party(),f.cart))).isTrue();assertThat(fixture.carts.get(f.customer,f.cart).state()).isEqualTo("ACTIVE");UUID order=order();assertThat(tx().<Boolean>execute(s->fixture.checkout.recoveryEligible(f.customer.party(),f.cart))).isFalse();f.jdbc.update("DELETE FROM commerce.sales_order WHERE id=?",order);f.jdbc.update("DELETE FROM commerce.cart_line WHERE cart_id=?",f.cart);assertThat(tx().<Boolean>execute(s->fixture.checkout.recoveryEligible(f.customer.party(),f.cart))).isFalse();}

 @Test void hundredLineLimitAndWholesaleQuantityDoNotImposeWholeOrderMinimum(){var f=fixture.f;f.retail();for(int n=1;n<100;n++){UUID sku=UUID.randomUUID();fixture.extraSkus.add(sku);f.jdbc.update("INSERT INTO commerce.sku(id,created_by,updated_by,product_id,code,variant_name,unit,quantity_scale,pack_size) VALUES (?,'test','test',?,?,'Synthetic bounded cart SKU','SYNTH_UNIT',0,1)",sku,f.marketFixture.product,"SYNTH_"+sku);f.jdbc.update("INSERT INTO commerce.cart_line(id,created_by,updated_by,cart_id,sku_id,quantity) VALUES (?,'test','test',?,?,1)",UUID.randomUUID(),f.cart,sku);}assertThat(fixture.carts.get(f.customer,f.cart).lines()).hasSize(100);assertThatThrownBy(()->fixture.carts.set(f.customer,f.cart,UUID.randomUUID(),0,new CartValues.Quantity("2"),"hundred-one",UUID.randomUUID())).hasMessage("CART_RULE_VIOLATION");assertThat(fixture.carts.set(f.customer,f.cart,f.sku,0,new CartValues.Quantity("3"),"hundred-existing",UUID.randomUUID()).lines()).hasSize(100);UUID org=f.organization();var base=f.input("8.00");var input=new com.nigson.commerce.pricing.PricingValues.Input(f.code+"_WHOLESALE","NGN","DISTRIBUTOR",base.effectiveFrom(),base.effectiveUntil(),List.of(new com.nigson.commerce.pricing.PricingValues.Entry(f.sku,"1","8.00")));var draft=f.books.create(f.sales,input,"wholesale",UUID.randomUUID());var book=f.books.activate(f.finance,draft.id(),0,"Synthetic wholesale activation","wholesale-activate",UUID.randomUUID());f.jdbc.update("INSERT INTO commerce.price_assignment(id,created_by,updated_by,organization_id,market_id,price_book_id) VALUES (?,'test','test',?,?,?)",UUID.randomUUID(),org,f.market,book.id());f.jdbc.update("INSERT INTO commerce.wholesale_rule(id,created_by,updated_by,organization_id,sku_id,market_id,minimum_quantity,pack_multiple,minimum_order_amount,rule_revision) VALUES (?,'test','test',?,?,?,2,2,100,1)",UUID.randomUUID(),org,f.sku,f.market);var c=fixture.carts.create(f.customer,new CartValues.Create(f.market,org),"organization",UUID.randomUUID());assertThatThrownBy(()->fixture.carts.set(f.customer,c.id(),f.sku,0,new CartValues.Quantity("3"),"odd",UUID.randomUUID())).hasMessage("CART_RULE_VIOLATION");var added=fixture.carts.set(f.customer,c.id(),f.sku,0,new CartValues.Quantity("2"),"even",UUID.randomUUID());assertThat(added.lines().getFirst().quantity()).isEqualTo("2");assertThat(added.version()).isEqualTo(1);}
 @Test void duplicateCommandRaceHasOneEffectAndConflictingHashFails()throws Exception{var f=fixture.f;f.retail();try(var pool=Executors.newFixedThreadPool(12)){var start=new CountDownLatch(1);var work=new ArrayList<Future<Object>>();for(int n=0;n<12;n++)work.add(pool.submit(()->{start.await();try{return fixture.carts.set(f.customer,f.cart,f.sku,0,new CartValues.Quantity("3"),"duplicate",UUID.randomUUID());}catch(Problem.Failure|com.nigson.commerce.platform.PlatformStore.Conflict e){return e.getMessage();}}));start.countDown();for(var future:work){var result=future.get(20,TimeUnit.SECONDS);if(result instanceof CartValues.Cart c)assertThat(c.version()).isEqualTo(1);else assertThat(result).isEqualTo("IDEMPOTENCY_IN_PROGRESS");}}var accepted=fixture.carts.set(f.customer,f.cart,f.sku,0,new CartValues.Quantity("3"),"duplicate",UUID.randomUUID());assertThat(accepted.version()).isEqualTo(1);assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.audit_record WHERE resource_id=? AND action='CART_SET'",Integer.class,f.cart)).isEqualTo(1);assertThat(f.metrics.get("nigson.cart.commands").tag("operation","SET").counter().count()).isEqualTo(1);assertThatThrownBy(()->fixture.carts.set(f.customer,f.cart,f.sku,0,new CartValues.Quantity("4"),"duplicate",UUID.randomUUID())).hasMessage("IDEMPOTENCY_HASH_MISMATCH");}

}
